// Retire the previous site's service worker at its original URL so returning
// visitors stop receiving cached pages. The new site does not register a worker.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name.startsWith('chirpy-')).map((name) => caches.delete(name)),
      );
      await self.registration.unregister();

      const windows = await self.clients.matchAll({ type: 'window' });
      await Promise.allSettled(windows.map((client) => client.navigate(client.url)));
    })(),
  );
});
